import java.util.*;

class Solution {
    private int[] w;
    private int t, n;
    private boolean[] failed;               // masks already proven impossible

    public boolean canShareFairly(int[] nums, int k) {
        int sum = 0;
        for (int x : nums) sum += x;
        if (sum % k != 0) return false;
        t = sum / k;
        n = nums.length;
        w = nums.clone();
        Arrays.sort(w);
        for (int i = 0, j = n - 1; i < j; i++, j--) { int tmp = w[i]; w[i] = w[j]; w[j] = tmp; } // descending
        if (w[0] > t) return false;
        failed = new boolean[1 << n];
        return dfs(0, 0);
    }

    // cur = how full the current bucket is
    private boolean dfs(int mask, int cur) {
        if (mask == (1 << n) - 1) return true;
        if (failed[mask]) return false;
        for (int i = 0; i < n; i++) {
            if ((mask >> i & 1) == 1 || cur + w[i] > t) continue;
            if (dfs(mask | (1 << i), (cur + w[i]) % t)) return true; // full bucket -> next starts at 0
        }
        failed[mask] = true;
        return false;
    }
}

