class Solution:
    def canShareFairly(self, nums: List[int], k: int) -> bool:
        s = sum(nums)
        if s % k: return False
        t = s // k
        nums = sorted(nums, reverse=True)
        if nums[0] > t: return False
        n = len(nums)
        @lru_cache(maxsize=None)
        def go(mask, cur):
            if mask == (1 << n) - 1: return True
            for i in range(n):
                if not mask >> i & 1 and cur + nums[i] <= t:
                    if go(mask | 1 << i, (cur + nums[i]) % t): return True
            return False
        return go(0, 0)

