function canShareFairly(nums, k) {
  const s = nums.reduce((a, b) => a + b, 0); if (s % k) return false;
  const t = s / k, n = nums.length, full = (1 << n) - 1;
  const rem = new Int32Array(1 << n).fill(-1); rem[0] = 0;
  for (let m = 0; m <= full; m++) {
    if (rem[m] < 0) continue;
    for (let i = 0; i < n; i++) {
      if (m >> i & 1) continue;
      const nm = m | (1 << i);
      if (rem[nm] >= 0) continue;
      if (rem[m] + nums[i] <= t) rem[nm] = (rem[m] + nums[i]) % t;
    }
  }
  return rem[full] === 0;
}
